<?php
declare(strict_types=1);

if($path!=='/admin/cache')return;
if(!(user()['is_admin']??false)){http_response_code(403);exit('Forbidden');}
if($method==='POST'){verify_csrf();smart_cache_clear();audit('clear','smart_cache',null,['scope'=>'all']);flash('success','Smart cache cleared. Current data will be rebuilt as pages are requested.');redirect('/admin/cache');}
$status=smart_cache_status();$requests=$status['hits']+$status['misses'];$hitRate=$requests?($status['hits']/$requests*100):0;
layout('Smart cache',function()use($status,$hitRate){?><div class="actions"><h1 style="margin:0">Smart cache</h1><span class="spacer"></span><a class="btn secondary" href="/admin/health">System health</a></div><div class="grid"><div class="card"><div class="metric"><?=e($status['backend'])?></div>Cache backend</div><div class="card"><div class="metric"><?=number_format($status['hits'])?></div>Cache hits</div><div class="card"><div class="metric"><?=number_format($status['misses'])?></div>Cache misses</div><div class="card"><div class="metric"><?=number_format($hitRate,1)?>%</div>Hit rate</div><div class="card"><div class="metric"><?=number_format($status['writes'])?></div>Rebuilt entries</div><div class="card"><div class="metric"><?=$status['entries']===null?'Managed':number_format($status['entries'])?></div>Stored entries</div></div><div class="card"><h2>Dependency-aware invalidation</h2><p>Cached contacts, opportunities, dashboard metrics, and reports record the data revisions they depend on. Application and API writes increment only the affected revisions, so unrelated cached results remain reusable.</p><p><strong>Dependency revisions:</strong> <?=number_format($status['revisions'])?><br><strong>Filesystem size:</strong> <?=number_format($status['bytes']/1024,1)?> KB<br><strong>Last activity:</strong> <?=e($status['updated_at']?:'No cache activity yet')?></p><form method="post" onsubmit="return confirm('Clear all cached CRM results? They will rebuild automatically.')"><input type="hidden" name="_csrf" value="<?=csrf()?>"><button class="danger">Clear smart cache</button></form></div><?php });exit;
